// g2_ghs_check.rs -- single-file exact check for the odd-characteristic GHS / Weil-descent
// (2,...,2)-cover question on EcGFp5 and EcMasFp5.  Plain `rustc -O`, no crates.
// Field: K = F_{p^5} = F_p[z]/(z^5-3), p = 2^64-2^32+1, k = F_p.  sigma = p-power Frobenius of K/k.
// For a curve y^2 = f(x) over K (f possibly after a Moebius change of x) the GHS cover is the
// compositum of the conjugate double covers y_i^2 = f^{sigma^i}(x).  Its function field is the
// Kummer extension of K(x) generated by sqrt(f_i).  With V = <[f_0..f_4]> in K(x)*/squares,
//   m = dim_F2 V,   B = {points of P^1(Kbar) where some v in V has odd valuation},
//   genus(C) = 1 + 2^(m-2) * (|B| - 4)        (Riemann-Hurwitz, inertia of order 2 at every b in B).
// A relation prod_{i in S} f_i = square in K(x) means: monic part is a square in K[x] AND the
// product of leading coefficients is a square in K.
use std::cmp::Ordering;

const P: u64 = 0xFFFF_FFFF_0000_0001;
type K = [u64; 5];
const ZERO: K = [0; 5];
const ONE: K = [1, 0, 0, 0, 0];
type Poly = Vec<K>;
type Big = Vec<u64>;

// ---------- F_p ----------
fn addp(a: u64, b: u64) -> u64 { let s = a as u128 + b as u128; (if s >= P as u128 { s - P as u128 } else { s }) as u64 }
fn subp(a: u64, b: u64) -> u64 { if a >= b { a - b } else { (P - b) + a } }
fn mulp(a: u64, b: u64) -> u64 { ((a as u128 * b as u128) % (P as u128)) as u64 }
fn powp(mut a: u64, mut e: u64) -> u64 { let mut r = 1u64; while e > 0 { if e & 1 == 1 { r = mulp(r, a); } a = mulp(a, a); e >>= 1; } r }
fn invp(a: u64) -> u64 { powp(a, P - 2) }
fn negp(a: u64) -> u64 { if a == 0 { 0 } else { P - a } }
fn legp(a: u64) -> i32 { if a == 0 { 0 } else if powp(a, (P - 1) / 2) == 1 { 1 } else { -1 } }

// ---------- minimal bigint (little endian u64 limbs) ----------
fn btrim(a: &mut Big) { while a.len() > 1 && *a.last().unwrap() == 0 { a.pop(); } }
fn big_mul_small(a: &Big, m: u64) -> Big { let mut r = Vec::new(); let mut c: u128 = 0; for &x in a { let t = x as u128 * m as u128 + c; r.push(t as u64); c = t >> 64; } if c > 0 { r.push(c as u64); } r }
fn big_add_small(a: &Big, m: u64) -> Big { let mut r = a.clone(); let mut c = m as u128; for i in 0..r.len() { let t = r[i] as u128 + c; r[i] = t as u64; c = t >> 64; if c == 0 { break; } } if c > 0 { r.push(c as u64); } r }
fn big_sub_small(a: &Big, m: u64) -> Big { let mut r = a.clone(); let mut b = m as u128; for i in 0..r.len() { let x = r[i] as u128; if x >= b { r[i] = (x - b) as u64; b = 0; break; } else { r[i] = (x + (1u128 << 64) - b) as u64; b = 1; } } assert!(b == 0); btrim(&mut r); r }
fn big_divrem_small(a: &Big, d: u64) -> (Big, u64) { let mut r = vec![0u64; a.len()]; let mut rem: u128 = 0; for i in (0..a.len()).rev() { let cur = (rem << 64) | a[i] as u128; r[i] = (cur / d as u128) as u64; rem = cur % d as u128; } btrim(&mut r); (r, rem as u64) }
fn big_shr32(a: &Big) -> Big { let mut r = vec![0u64; a.len()]; for i in 0..a.len() { r[i] = (a[i] >> 32) | if i + 1 < a.len() { a[i + 1] << 32 } else { 0 }; } btrim(&mut r); r }
fn big_bitlen(a: &Big) -> usize { let mut a2 = a.clone(); btrim(&mut a2); let top = *a2.last().unwrap(); if a2.len() == 1 && top == 0 { 0 } else { 64 * (a2.len() - 1) + (64 - top.leading_zeros() as usize) } }
fn big_bit(a: &Big, i: usize) -> bool { (a[i / 64] >> (i % 64)) & 1 == 1 }
fn big_pow_p(n: u32) -> Big { let mut r = vec![1u64]; for _ in 0..n { r = big_mul_small(&r, P); } r }

// ---------- K = F_p[z]/(z^5-3) ----------
fn omega() -> u64 { powp(3, (P - 1) / 5) } // z^p = omega * z
fn omega_pows() -> [u64; 5] { let w = omega(); let mut r = [1u64; 5]; for i in 1..5 { r[i] = mulp(r[i - 1], w); } r }
fn kadd(a: &K, b: &K) -> K { let mut c = ZERO; for i in 0..5 { c[i] = addp(a[i], b[i]); } c }
fn ksub(a: &K, b: &K) -> K { let mut c = ZERO; for i in 0..5 { c[i] = subp(a[i], b[i]); } c }
fn kneg(a: &K) -> K { let mut c = ZERO; for i in 0..5 { c[i] = negp(a[i]); } c }
fn kscale(a: &K, s: u64) -> K { let mut c = ZERO; for i in 0..5 { c[i] = mulp(a[i], s); } c }
fn kmul(a: &K, b: &K) -> K {
    let mut c = ZERO;
    for i in 0..5 { if a[i] == 0 { continue; } for j in 0..5 { let t = mulp(a[i], b[j]); let k = i + j; if k < 5 { c[k] = addp(c[k], t); } else { c[k - 5] = addp(c[k - 5], mulp(t, 3)); } } }
    c
}
fn kfrob(a: &K, wp: &[u64; 5]) -> K { let mut c = ZERO; for i in 0..5 { c[i] = mulp(a[i], wp[i]); } c }
fn kfrobn(a: &K, wp: &[u64; 5], n: usize) -> K { let mut c = *a; for _ in 0..n { c = kfrob(&c, wp); } c }
fn kpow(a: &K, e: &Big) -> K { let mut r = ONE; let n = big_bitlen(e); for i in (0..n).rev() { r = kmul(&r, &r); if big_bit(e, i) { r = kmul(&r, a); } } r }
fn kpow_u64(a: &K, mut e: u64) -> K { let mut r = ONE; let mut b = *a; while e > 0 { if e & 1 == 1 { r = kmul(&r, &b); } b = kmul(&b, &b); e >>= 1; } r }
fn knorm(a: &K, wp: &[u64; 5]) -> u64 { let mut t = *a; for k in 1..5 { t = kmul(&t, &kfrobn(a, wp, k)); } assert!(t[1..].iter().all(|&x| x == 0), "norm not in F_p"); t[0] }
fn kchi(a: &K, wp: &[u64; 5]) -> i32 { legp(knorm(a, wp)) } // a^((Q-1)/2) = N(a)^((p-1)/2)
fn kinv(a: &K, wp: &[u64; 5]) -> K { let mut t = ONE; for k in 1..5 { t = kmul(&t, &kfrobn(a, wp, k)); } let n = knorm(a, wp); assert!(n != 0); kscale(&t, invp(n)) }
fn kfp(x: u64) -> K { [x, 0, 0, 0, 0] }
fn kz(i: usize) -> K { let mut c = ZERO; c[i] = 1; c }
fn kin_fp(a: &K) -> bool { a[1..].iter().all(|&x| x == 0) }
struct Rng(u64);
impl Rng { fn next(&mut self) -> u64 { let mut x = self.0; x ^= x >> 12; x ^= x << 25; x ^= x >> 27; self.0 = x; x.wrapping_mul(0x2545F4914F6CDD1D) }
    fn kel(&mut self) -> K { let mut c = ZERO; for i in 0..5 { c[i] = self.next() % P; } c } }
// Tonelli-Shanks in K; Q-1 = 2^32 * t, t odd
fn ksqrt(a: &K, wp: &[u64; 5]) -> Option<K> {
    if *a == ZERO { return Some(ZERO); }
    if kchi(a, wp) != 1 { return None; }
    let qm1 = big_sub_small(&big_pow_p(5), 1);
    let t = big_shr32(&qm1); assert!(t[0] & 1 == 1);
    let mut zz = ONE; let mut kk = 1u64; loop { zz = [kk, 1, 0, 0, 0]; if kchi(&zz, wp) == -1 { break; } kk += 1; }
    let mut c = kpow(&zz, &t);
    let tp1h = { let x = big_add_small(&t, 1); big_divrem_small(&x, 2).0 };
    let mut r = kpow(a, &tp1h);
    let mut tt = kpow(a, &t);
    let mut m = 32usize;
    while tt != ONE {
        let mut i = 0usize; let mut x = tt; while x != ONE { x = kmul(&x, &x); i += 1; assert!(i < m); }
        let mut b = c; for _ in 0..(m - i - 1) { b = kmul(&b, &b); }
        r = kmul(&r, &b); c = kmul(&b, &b); tt = kmul(&tt, &c); m = i;
    }
    assert!(kmul(&r, &r) == *a);
    Some(r)
}
// cube root in K for a cube (3 || Q-1 because 3 || p-1)
fn kcuberoot(w: &K, wp: &[u64; 5]) -> Option<K> {
    if powp(knorm(w, wp), (P - 1) / 3) != 1 { return None; }
    let qm1 = big_sub_small(&big_pow_p(5), 1);
    let (r, rem) = big_divrem_small(&qm1, 3); assert!(rem == 0);
    let rm3 = big_divrem_small(&r, 3).1; assert!(rm3 != 0);
    let j = if rm3 == 1 { 2 } else { 1 };
    let s = { let x = big_add_small(&big_mul_small(&r, j), 1); let (q, rr) = big_divrem_small(&x, 3); assert!(rr == 0); q };
    let root = kpow(w, &s);
    let cube = kmul(&kmul(&root, &root), &root);
    assert!(cube == *w);
    Some(root)
}

// ---------- polynomials over K (low -> high) ----------
fn ptrim(p: &mut Poly) { while let Some(l) = p.last() { if *l == ZERO { p.pop(); } else { break; } } }
fn pdeg(p: &Poly) -> i32 { p.len() as i32 - 1 }
fn padd(a: &Poly, b: &Poly) -> Poly { let n = a.len().max(b.len()); let mut r = vec![ZERO; n]; for i in 0..n { let x = if i < a.len() { a[i] } else { ZERO }; let y = if i < b.len() { b[i] } else { ZERO }; r[i] = kadd(&x, &y); } ptrim(&mut r); r }
fn psub(a: &Poly, b: &Poly) -> Poly { let n = a.len().max(b.len()); let mut r = vec![ZERO; n]; for i in 0..n { let x = if i < a.len() { a[i] } else { ZERO }; let y = if i < b.len() { b[i] } else { ZERO }; r[i] = ksub(&x, &y); } ptrim(&mut r); r }
fn pmul(a: &Poly, b: &Poly) -> Poly { if a.is_empty() || b.is_empty() { return vec![]; } let mut r = vec![ZERO; a.len() + b.len() - 1]; for i in 0..a.len() { for j in 0..b.len() { let t = kmul(&a[i], &b[j]); r[i + j] = kadd(&r[i + j], &t); } } ptrim(&mut r); r }
fn pscale(a: &Poly, s: &K) -> Poly { let mut r: Poly = a.iter().map(|c| kmul(c, s)).collect(); ptrim(&mut r); r }
fn pderiv(a: &Poly) -> Poly { let mut r = Vec::new(); for i in 1..a.len() { r.push(kscale(&a[i], i as u64)); } ptrim(&mut r); r }
fn psigma(a: &Poly, wp: &[u64; 5]) -> Poly { a.iter().map(|c| kfrob(c, wp)).collect() }
fn pdivrem(a: &Poly, b: &Poly, wp: &[u64; 5]) -> (Poly, Poly) {
    assert!(!b.is_empty()); let mut r = a.clone(); ptrim(&mut r);
    let db = b.len() - 1; let inv = kinv(b.last().unwrap(), wp);
    if r.len() < b.len() { return (vec![], r); }
    let mut q = vec![ZERO; r.len() - db];
    while r.len() >= b.len() && !r.is_empty() {
        let sh = r.len() - b.len(); let c = kmul(r.last().unwrap(), &inv); q[sh] = c;
        for i in 0..b.len() { let t = kmul(&c, &b[i]); r[sh + i] = ksub(&r[sh + i], &t); }
        ptrim(&mut r);
    }
    ptrim(&mut q); (q, r)
}
fn pmonic(a: &Poly, wp: &[u64; 5]) -> Poly { let inv = kinv(a.last().unwrap(), wp); pscale(a, &inv) }
fn pgcd(a: &Poly, b: &Poly, wp: &[u64; 5]) -> Poly {
    let mut x = a.clone(); let mut y = b.clone(); ptrim(&mut x); ptrim(&mut y);
    while !y.is_empty() { let (_, r) = pdivrem(&x, &y, wp); x = y; y = r; }
    if x.is_empty() { x } else { pmonic(&x, wp) }
}
fn pmulmod(a: &Poly, b: &Poly, m: &Poly, wp: &[u64; 5]) -> Poly { pdivrem(&pmul(a, b), m, wp).1 }
fn ppowmod(a: &Poly, mut e: u64, m: &Poly, wp: &[u64; 5]) -> Poly { let mut r: Poly = vec![ONE]; let mut b = pdivrem(a, m, wp).1; while e > 0 { if e & 1 == 1 { r = pmulmod(&r, &b, m, wp); } b = pmulmod(&b, &b, m, wp); e >>= 1; } r }
// number of distinct roots of f in K = deg gcd(x^Q - x, f)
fn nroots_in_k(f: &Poly, wp: &[u64; 5]) -> i32 {
    let x: Poly = vec![ZERO, ONE]; let mut h = x.clone();
    for _ in 0..5 { h = ppowmod(&h, P, f, wp); }
    let g = pgcd(&psub(&h, &x), f, wp); pdeg(&g)
}
// substitution x = (a x' + b)/(c x' + d) into a binary form of degree n with coefficient list coefs[k] of X^k Z^(n-k)
fn subst_form(coefs: &Poly, n: usize, a: &K, b: &K, c: &K, d: &K) -> Poly {
    let lin1: Poly = { let mut v = vec![*b, *a]; ptrim(&mut v); v };
    let lin2: Poly = { let mut v = vec![*d, *c]; ptrim(&mut v); v };
    let mut res: Poly = vec![];
    for k in 0..coefs.len() {
        let mut t: Poly = vec![coefs[k]]; ptrim(&mut t);
        for _ in 0..k { t = pmul(&t, &lin1); }
        for _ in 0..(n - k) { t = pmul(&t, &lin2); }
        res = padd(&res, &t);
    }
    res
}
// monic square root
fn psqrt_monic(q: &Poly) -> Option<Poly> {
    let n = q.len() - 1; if n % 2 == 1 { return None; } let d = n / 2;
    let inv2 = invp(2);
    let mut h = vec![ZERO; d + 1]; h[d] = ONE;
    for k in 1..=d {
        let idx = 2 * d - k; let mut s = q[idx];
        if d >= 1 + (d - k) { for i in (d - k + 1)..d { let j = idx as i64 - i as i64; if j >= (d - k + 1) as i64 && j < d as i64 { let t = kmul(&h[i], &h[j as usize]); s = ksub(&s, &t); } } }
        h[d - k] = kscale(&s, inv2);
    }
    if pmul(&h, &h) == *q { Some(h) } else { None }
}
fn is_square_poly(f: &Poly, wp: &[u64; 5]) -> bool {
    if f.is_empty() { return false; }
    if (f.len() - 1) % 2 == 1 { return false; }
    let lc = *f.last().unwrap(); if kchi(&lc, wp) != 1 { return false; }
    let q = pmonic(f, wp); psqrt_monic(&q).is_some()
}

// ---------- GHS-cover analysis ----------
struct An { masks: Vec<u32>, rank: usize, m: usize, nb: i64, genus: i64, shift_closed: bool, sqfree: bool }
fn f2rank(v: &[u32]) -> usize { let mut basis: Vec<u32> = vec![]; for &x in v { let mut y = x; for &b in &basis { if (y ^ b) < y { y ^= b; } } if y != 0 { basis.push(y); basis.sort_by(|a, b| b.cmp(a)); } } basis.len() }
fn analyze(f: &Poly, wp: &[u64; 5]) -> An {
    let mut conj: Vec<Poly> = vec![f.clone()]; for i in 1..5 { let p = psigma(&conj[i - 1], wp); conj.push(p); }
    let mut sqfree = true; for c in &conj { let g = pgcd(c, &pderiv(c), wp); if pdeg(&g) > 0 { sqfree = false; } }
    let mut masks = vec![];
    for mask in 1u32..32 { let mut prod: Poly = vec![ONE]; for i in 0..5 { if mask >> i & 1 == 1 { prod = pmul(&prod, &conj[i]); } } if is_square_poly(&prod, wp) { masks.push(mask); } }
    let rotl = |x: u32| ((x << 1) | (x >> 4)) & 31;
    let shift_closed = masks.iter().all(|&x| masks.contains(&rotl(x)));
    let rank = f2rank(&masks); let m = 5 - rank;
    // B = roots of lcm(f_i) (+ infinity if some f_i has odd degree)   [valid when each f_i is squarefree]
    let mut l: Poly = pmonic(&conj[0], wp);
    for i in 1..5 { let g = pgcd(&l, &conj[i], wp); let prod = pmul(&l, &pmonic(&conj[i], wp)); l = pdivrem(&prod, &g, wp).0; }
    let inf = conj.iter().any(|c| (pdeg(c) % 2) == 1);
    let nb = pdeg(&l) as i64 + if inf { 1 } else { 0 };
    let num = (nb - 4) * (1i64 << m); assert!(num % 4 == 0 || nb == 4);
    let genus = 1 + num / 4;
    An { masks, rank, m, nb, genus, shift_closed, sqfree }
}
fn show(name: &str, a: &An) {
    println!("  [{}] squarefree_conjugates={} relations(masks of S with prod f_i square)={:?} closed_under_shift={} rank={} m={} |B|={} genus={} hyperelliptic_possible={}",
        name, a.sqfree, a.masks, a.shift_closed, a.rank, a.m, a.nb, a.genus, if a.m >= 4 { "no (m>=4 forces non-hyperelliptic)" } else { "check" });
}
fn linprod(roots: &[K]) -> Poly { let mut p: Poly = vec![ONE]; for r in roots { p = pmul(&p, &vec![kneg(r), ONE]); } p }
fn jinv(a: &K, b: &K, wp: &[u64; 5]) -> K { // short Weierstrass y^2 = x^3 + a x + b
    let a3 = kmul(&kmul(a, a), a); let num = kscale(&a3, 4 * 1728 % P); let den = kadd(&kscale(&a3, 4), &kscale(&kmul(b, b), 27)); kmul(&num, &kinv(&den, wp)) }
fn kstr(a: &K) -> String { format!("[{},{},{},{},{}]", a[0], a[1], a[2], a[3], a[4]) }

fn main() {
    let wp = omega_pows(); let w = wp[1]; let mut rng = Rng(0x9E3779B97F4A7C15);
    let mut ok = true; let mut chk = |name: &str, c: bool| { println!("  CHECK {:<62} {}", name, if c { "PASS" } else { "FAIL" }); if !c { ok = false; } };
    println!("== F1: field and Frobenius");
    chk("p = 2^64-2^32+1", P == 18446744069414584321u64);
    chk("p mod 5 == 1", P % 5 == 1);
    chk("omega=3^((p-1)/5) != 1 (so z^5-3 irreducible), omega^5 == 1", w != 1 && powp(w, 5) == 1);
    let zk = kz(1); let zp = kpow_u64(&zk, P);
    chk("z^p (generic square-multiply in K) == omega*z", zp == kscale(&zk, w));
    println!("  omega = {}", w);
    let mut fr_ok = true; for _ in 0..4 { let a = rng.kel(); if kpow_u64(&a, P) != kfrob(&a, &wp) { fr_ok = false; } }
    chk("a^p == diagonal Frobenius on 4 random elements", fr_ok);
    let q_big = big_pow_p(5); let qm1h = { let x = big_sub_small(&q_big, 1); big_divrem_small(&x, 2).0 };
    let mut chi_ok = true; for _ in 0..6 { let a = rng.kel(); let e = kpow(&a, &qm1h); let direct = if e == ONE { 1 } else if e == kneg(&ONE) { -1 } else { 0 }; if direct != kchi(&a, &wp) { chi_ok = false; } }
    chk("chi_K via norm == Euler a^((p^5-1)/2) on 6 random elements", chi_ok);
    let mut inv_ok = true; for _ in 0..4 { let a = rng.kel(); if kmul(&a, &kinv(&a, &wp)) != ONE { inv_ok = false; } } chk("K inverse", inv_ok);
    let mut sq_ok = true; for _ in 0..3 { let a = rng.kel(); let s = kmul(&a, &a); match ksqrt(&s, &wp) { Some(r) => { if kmul(&r, &r) != s { sq_ok = false; } } None => sq_ok = false } } chk("Tonelli-Shanks sqrt in K", sq_ok);

    println!("== F2: the two curves (frozen-source constants)");
    let b263 = kscale(&kz(1), 263);
    // EcGFp5: y^2 = x(x^2+2x+263z)
    let f_gfp5: Poly = vec![ZERO, b263, kfp(2), ONE];
    let q_gfp5: Poly = vec![b263, kfp(2), ONE];
    // short Weierstrass from a=2, b=263z:  A=(3b-a^2)/3, B=a(2a^2-9b)/27
    let inv3 = invp(3); let inv27 = invp(27);
    let a_sw = kadd(&b263, &kfp(mulp(negp(4), inv3)));
    let b_sw = { let t = ksub(&kfp(8), &kscale(&b263, 9)); kscale(&kscale(&t, 2), inv27) };
    let a_hm: K = [6148914689804861439, 263, 0, 0, 0]; let b_hm: K = [15713893096167979237, 6148914689804861265, 0, 0, 0];
    chk("EcGFp5 short-Weierstrass A,B from (a=2,b=263z) == HackMD constants", a_sw == a_hm && b_sw == b_hm);
    let chi_b = kchi(&b263, &wp); let dq = ksub(&kfp(4), &kscale(&b263, 4)); let chi_dq = kchi(&dq, &wp);
    println!("  chi_K(b=263z) = {}   chi_K(disc of x^2+2x+b = 4-4b) = {}", chi_b, chi_dq);
    chk("b=263z is a non-square in K (Pornin: double-odd)", chi_b == -1);
    let nr_g = nroots_in_k(&f_gfp5, &wp); let nr_q = nroots_in_k(&q_gfp5, &wp);
    println!("  EcGFp5: #roots of f in K = {}   #roots of x^2+2x+b in K = {}   => |E[2](K)| = {}", nr_g, nr_q, if nr_g == 0 { 1 } else if nr_g == 1 { 2 } else { 4 });
    chk("EcGFp5: exactly one rational 2-torsion x-coordinate (x=0); other two conjugate over K", nr_g == 1 && nr_q == 0 && chi_dq == -1);
    let j_g = jinv(&a_sw, &b_sw, &wp);
    println!("  j(EcGFp5) = {}   in F_p? {}   sigma(j)==j? {}", kstr(&j_g), kin_fp(&j_g), kfrob(&j_g, &wp) == j_g);
    chk("EcGFp5: j not in F_p (E is not a twist of a subfield curve)", !kin_fp(&j_g));
    // 2-isogenous curve E' = E/<(0,0)>: y^2 = x(x^2 - 2a x + a^2-4b)
    let a2 = kfp(negp(4)); let b2 = ksub(&kfp(4), &kscale(&b263, 4)); let f_iso: Poly = vec![ZERO, b2, a2, ONE]; let q_iso: Poly = vec![b2, a2, ONE];
    let d_iso = ksub(&kmul(&a2, &a2), &kscale(&b2, 4)); // = 16 b
    println!("  2-isogenous E': disc(x^2-4x+4(1-b)) = 16b => chi = {}, #roots of f' in K = {}", kchi(&d_iso, &wp), nroots_in_k(&f_iso, &wp));
    chk("E' (2-isogeny via (0,0)) again has exactly one rational 2-torsion point", nroots_in_k(&f_iso, &wp) == 1 && nroots_in_k(&q_iso, &wp) == 0);
    // EcMasFp5: y^2 = x^3 + 3x + 8 z^4
    let b_mas = kscale(&kz(4), 8); let f_mas: Poly = vec![b_mas, kfp(3), ZERO, ONE];
    let disc_mas = ksub(&kscale(&kfp(1), negp(108)), &kscale(&kmul(&b_mas, &b_mas), 27));
    println!("  EcMasFp5: chi_K(disc f)= {}   #roots of f in K = {}", kchi(&disc_mas, &wp), nroots_in_k(&f_mas, &wp));
    chk("EcMasFp5: f irreducible over K (no rational 2-torsion); disc is a square (3-cycle)", nroots_in_k(&f_mas, &wp) == 0 && kchi(&disc_mas, &wp) == 1);
    let j_m = jinv(&kfp(3), &b_mas, &wp);
    println!("  j(EcMasFp5) = {}   in F_p? {}", kstr(&j_m), kin_fp(&j_m));
    chk("EcMasFp5: j not in F_p", !kin_fp(&j_m));

    println!("== F3: validation of the relation/genus machinery on toy models with known answers");
    let t1: Poly = vec![kfp(7), kfp(3), ZERO, ONE]; // coefficients in F_p
    let a1 = analyze(&t1, &wp); show("toy1 f=x^3+3x+7 over F_p  (expect m=1,|B|=4,g=1)", &a1);
    chk("toy1: m=1, |B|=4, genus 1, 15 even-weight relations", a1.m == 1 && a1.nb == 4 && a1.genus == 1 && a1.masks.len() == 15);
    let orb: Vec<K> = (0..4).map(|i| kscale(&kz(1), wp[i])).collect(); // z, wz, w^2 z, w^3 z  (4 of the 5 conjugates of z)
    let t2 = linprod(&orb); let a2_ = analyze(&t2, &wp); show("toy2 f=prod_{i<4}(x-w^i z)  (literature (d,n)=(5,4): m=4,g=5)", &a2_);
    chk("toy2: weak class has m=4, |B|=5, genus 5 (= d*g0), single relation 11111", a2_.m == 4 && a2_.nb == 5 && a2_.genus == 5 && a2_.masks == vec![31]);
    let mut cns = kz(0); let mut c = 2u64; loop { cns = kfp(c); if kchi(&cns, &wp) == -1 { break; } c += 1; }
    let t3 = pscale(&t2, &cns); let a3 = analyze(&t3, &wp); show("toy3 = toy2 times a non-square constant (expect m=5,g=9)", &a3);
    chk("toy3: non-square leading constant kills the relation: m=5, genus 9", a3.m == 5 && a3.genus == 9 && a3.masks.is_empty());
    let t4: Poly = vec![ONE, kz(1), ZERO, ONE]; let a4 = analyze(&t4, &wp); show("toy4 generic cubic x^3+zx+1 (expect m=5,|B|=16,g=97)", &a4);
    chk("toy4: generic cubic gives m=5, |B|=16, genus 97", a4.m == 5 && a4.nb == 16 && a4.genus == 97);

    println!("== F4: canonical x-coordinate cover (T=O, M=id) of the two curves");
    let ag = analyze(&f_gfp5, &wp); show("EcGFp5   y^2=x(x^2+2x+263z)", &ag);
    let am = analyze(&f_mas, &wp); show("EcMasFp5 y^2=x^3+3x+8z^4", &am);
    chk("EcGFp5 canonical: m=5, |B|=12 (0, inf, 10 roots), genus 65", ag.m == 5 && ag.nb == 12 && ag.genus == 65);
    chk("EcMasFp5 canonical: m=5, |B|=16, genus 97", am.m == 5 && am.nb == 16 && am.genus == 97);

    println!("== F5: random Moebius changes x -> (ax+b)/(cx+d), a,b,c,d in K (the degree-2 maps E->P^1 with T=O)");
    for (nm, f) in [("EcGFp5", &f_gfp5), ("EcMasFp5", &f_mas)] {
        let mut gens = vec![];
        for _ in 0..3 {
            let (a, b, c, d) = (rng.kel(), rng.kel(), rng.kel(), rng.kel());
            if ksub(&kmul(&a, &d), &kmul(&b, &c)) == ZERO { continue; }
            let fq = subst_form(f, 4, &a, &b, &c, &d); let an = analyze(&fq, &wp); gens.push((an.m, an.nb, an.genus));
        }
        println!("  {} random M: (m,|B|,genus) = {:?}", nm, gens);
        chk(&format!("{} random M: all m=5, |B|=20, genus 129", nm), gens.iter().all(|&x| x == (5, 20, 129)));
    }

    println!("== F6: best explicit cover found for EcMasFp5 (cubic normalised to an F_p-rational cubic)");
    // F_3 = X^3 + 3 X Z^2 + d3 Z^3 ;  Hessian = -9 (X^2 + d3 XZ - Z^2)
    let d3 = b_mas; let disc_h = kadd(&kmul(&d3, &d3), &kfp(4));
    match ksqrt(&disc_h, &wp) {
        None => { println!("  Hessian discriminant not a square: construction does not apply"); chk("Hessian roots in K", false); }
        Some(sq) => {
            let inv2k = kfp(invp(2));
            let u = kmul(&ksub(&sq, &d3), &inv2k); let v = kmul(&kneg(&kadd(&sq, &d3)), &inv2k);
            // x' = (x-u)/(x-v) <=> x = (v x' - u)/(x' - 1)
            let cub: Poly = f_mas.clone(); // coefficients of X^k Z^(3-k): [d3,3,0,1]
            let f3p = subst_form(&cub, 3, &v, &kneg(&u), &ONE, &kneg(&ONE));
            println!("  cubic form after x'=(x-u)/(x-v): degree {} coefficients of x'^2,x' = {} , {}", pdeg(&f3p), kstr(&f3p.get(2).copied().unwrap_or(ZERO)), kstr(&f3p.get(1).copied().unwrap_or(ZERO)));
            chk("Hessian roots diagonalise the cubic: x'^2 and x' coefficients vanish", f3p.len() == 4 && f3p[1] == ZERO && f3p[2] == ZERO);
            let alpha = f3p[3]; let delta = f3p[0]; let kappa = kmul(&kneg(&delta), &kinv(&alpha, &wp));
            let mut g0 = 2u64; while powp(g0, (P - 1) / 3) == 1 { g0 += 1; }
            let mut c0 = 0u64; for cand in [g0, mulp(g0, g0)] { let ratio = kmul(&kappa, &kinv(&kfp(cand), &wp)); if kcuberoot(&ratio, &wp).is_some() { c0 = cand; } }
            chk("kappa = -delta/alpha is a non-cube (cubic irreducible) and kappa/c0 is a cube for some c0 in F_p", c0 != 0 && powp(knorm(&kappa, &wp), (P - 1) / 3) != 1);
            let mu = kcuberoot(&kmul(&kappa, &kinv(&kfp(c0), &wp)), &wp).unwrap();
            // x = (v*mu x'' - u)/(mu x'' - 1)
            let a_ = kmul(&v, &mu); let b_ = kneg(&u); let c_ = mu; let d_ = kneg(&ONE);
            let f4 = subst_form(&f_mas, 4, &a_, &b_, &c_, &d_);
            let cubic_fp: Poly = vec![kfp(negp(c0)), ZERO, ZERO, ONE]; let b1 = kinv(&mu, &wp);
            let expect = pmul(&vec![kneg(&b1), ONE], &cubic_fp);
            let lc = *f4.last().unwrap(); let monic = pmonic(&f4, &wp);
            println!("  f'' = lc * (x - 1/mu) * (x^3 - c0), c0 = {}, 1/mu in F_p? {}", c0, kin_fp(&b1));
            chk("transformed quartic == lc*(x-1/mu)*(x^3-c0) with c0 in F_p (three branch points F_p-rational as a set)", monic == expect);
            let an = analyze(&f4, &wp); show("EcMasFp5 normalised cover", &an);
            chk("EcMasFp5 normalised cover: m=5, |B|=8, genus 33 (non-hyperelliptic)", an.m == 5 && an.nb == 8 && an.genus == 33);
        }
    }
    println!("== F7: best explicit cover found for EcGFp5 (quadratic factor -> F_p-rational quadratic, M(0)=0)");
    {   // roots of q = x^2+2x+b : r = -1 +- theta/2, theta^2 = D = 4-4b (non-square in K). Target pi = x^2 - c0, c0 in F_p non-square.
        let dd = dq; let mut c0 = 2u64; while legp(c0) != -1 { c0 += 1; }
        let ratio = kmul(&kfp(c0), &kinv(&dd, &wp)); let e = ksqrt(&ratio, &wp).expect("c0/D is a square in K");
        // x'' = M(x) = (al x+be)/(ga x+de) with ga=1, be=0, de=1-D/4, al=-e*D/2:  M(0)=0, M(roots of q) = +-sqrt(c0), M(inf) = -eD/2
        let ga = ONE; let de = ksub(&ONE, &kscale(&dd, invp(4))); let al = kneg(&kscale(&kmul(&e, &dd), invp(2))); let be = ZERO;
        // inverse substitution x = (de x'' - be)/(-ga x'' + al)
        let f4 = subst_form(&f_gfp5, 4, &de, &kneg(&be), &kneg(&ga), &al);
        let minf = kmul(&al, &kinv(&ga, &wp));
        let expect = pmul(&vec![ZERO, ONE], &pmul(&vec![kneg(&minf), ONE], &vec![kfp(negp(c0)), ZERO, ONE]));
        println!("  c0 = {}, M(inf) = -eD/2 in F_p? {}", c0, kin_fp(&minf));
        chk("transformed quartic == lc*x*(x-M(inf))*(x^2-c0): x=0 and the quadratic are F_p-rational", pmonic(&f4, &wp) == expect);
        let an = analyze(&f4, &wp); show("EcGFp5 explicit cover", &an);
        chk("EcGFp5 explicit cover: m=5, |B|=8, genus 33 (non-hyperelliptic)", an.m == 5 && an.nb == 8 && an.genus == 33);
    }
    println!("== F8: toy of the (2,2) pattern (two conjugate pairs) that the analysis allows for EcGFp5-type 2-torsion");
    {   let mut t = ZERO; let mut kk = 2u64; loop { t = [kk, 1, 0, 0, 0]; if kchi(&t, &wp) == -1 { break; } kk += 1; }
        let qa: Poly = vec![kneg(&t), ZERO, ONE]; let qb = psigma(&qa, &wp); let toy = pmul(&qa, &qb);
        let an = analyze(&toy, &wp); show("toy5 f=(x^2-t)(x^2-sigma t), t non-square", &an);
        chk("toy5: m=4, |B|=10, genus 25, single relation 11111", an.m == 4 && an.nb == 10 && an.genus == 25 && an.masks == vec![31]); }
    println!("== SUMMARY: all checks {}", if ok { "PASS" } else { "FAIL" });
    let _ = Ordering::Equal;
}
